insert into rule_versions (version, config, status, approved_by, approved_at, notes) values (1, $t${"version":"v1","approval":{"ownerApproved":true,"approvedBy":"project owner (founder's office)","approvedOn":"2026-10-07","nikhilProductionSignoff":"pending"},"timeline":{"minWeeksToDeadline":8},"size":{"commercialMin":500,"commercialMax":3000,"reviewUpperBand":3300},"budgetThresholdsInr":{"oneRoom":200000,"twoRooms":400000,"full1bhk":400000,"full2bhk":600000,"full3bhk":800000,"full4bhkOrVilla":1200000,"officePerSqft":1000},"localities":{"served":["kothrud","baner","aundh","wakad","koregaon park","kalyani nagar","viman nagar","hadapsar","magarpatta","nibm","kondhwa","undri","shivane","warje","erandwane","deccan","kharadi","pimpri","chinchwad","pimple saudagar","pimple nilakh","ravet","hinjewadi"],"edge":["talegaon"],"excluded":["nashik","mumbai","lonavala"],"cityGeneric":["pune","pune city","pcmc","pimpri chinchwad"]},"types":{"fit":["home","office","studio"],"notFit":["restaurant","hotel","gym","retail"],"unclear":["clinic","other"]},"vipReferrers":["Vikram Agarwal"]}$t$::jsonb, 'active', $t$project owner (founder's office)$t$, '2026-10-07', $t$Approved by project owner. Nikhil production sign-off pending.$t$) on conflict (version) do nothing;
insert into approved_texts (key, locale, body, status, version, approved_by, approved_at) values
($t$price_explanation$t$, 'en', $t$I can't give you a figure that would mean anything before a designer sees your home. The same kitchen can cost several times more depending on the materials. The consultation is free, and by the end of it the designer will give you a proper number.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$price_explanation$t$, 'hi', $t$डिज़ाइनर के घर देखे बिना कोई भी आंकड़ा बताना सही नहीं होगा। एक ही किचन, मटीरियल के हिसाब से, कई गुना महँगा हो सकता है। कंसल्टेशन बिल्कुल फ्री है, और उसके आख़िर में डिज़ाइनर आपको सही आंकड़ा बताएँगे।$t$, 'approved_pending_native_check', 1, $t$project owner$t$, '2026-10-07'),
($t$price_explanation$t$, 'mr', $t$डिझायनरने घर पाहिल्याशिवाय कोणताही आकडा सांगणं योग्य होणार नाही. एकच किचन, मटेरियलनुसार, कितीतरी पट महाग होऊ शकतं. कन्सल्टेशन पूर्णपणे मोफत आहे, आणि त्याच्या शेवटी डिझायनर तुम्हाला नेमका आकडा सांगतील.$t$, 'approved_pending_native_check', 1, $t$project owner$t$, '2026-10-07'),
($t$not_fit.area$t$, 'en', $t$Thank you for thinking of us. We only take projects in Pune and PCMC, because our contractors need to be on site every day. I'm sorry we can't help with this one.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$not_fit.area$t$, 'hi', $t$हमें याद करने के लिए धन्यवाद। हम केवल पुणे और पिंपरी-चिंचवड में प्रोजेक्ट लेते हैं, क्योंकि हमारे कॉन्ट्रैक्टर्स को रोज़ साइट पर रहना पड़ता है। माफ़ कीजिए, इस प्रोजेक्ट में हम मदद नहीं कर पाएँगे।$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.area$t$, 'mr', $t$आमची आठवण ठेवल्याबद्दल धन्यवाद. आम्ही फक्त पुणे आणि पिंपरी-चिंचवडमध्ये प्रोजेक्ट घेतो, कारण आमच्या कॉन्ट्रॅक्टर्सना रोज साइटवर असावं लागतं. क्षमस्व, या प्रोजेक्टमध्ये आम्ही मदत करू शकत नाही.$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.advisory$t$, 'en', $t$We're a full-service studio, so every project includes design and execution together. We don't do advice-only visits. If you decide on a full project, we'd love to hear from you.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$not_fit.advisory$t$, 'hi', $t$हम एक फुल-सर्विस स्टूडियो हैं, इसलिए हर प्रोजेक्ट में डिज़ाइन और एक्ज़िक्यूशन साथ-साथ होते हैं। हम सिर्फ़ सलाह वाली विज़िट नहीं करते। अगर आप पूरा प्रोजेक्ट करवाने का फ़ैसला करें, तो हमें ज़रूर याद कीजिएगा।$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.advisory$t$, 'mr', $t$आम्ही फुल-सर्व्हिस स्टुडिओ आहोत, त्यामुळे प्रत्येक प्रोजेक्टमध्ये डिझाइन आणि एक्झिक्यूशन एकत्र असतं. आम्ही फक्त सल्ला देणाऱ्या भेटी करत नाही. तुम्ही पूर्ण प्रोजेक्ट करायचं ठरवलंत, तर आम्हाला नक्की संपर्क करा.$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.type$t$, 'en', $t$We focus on homes and offices. A space like this has specialist requirements, so a studio that specialises in them will serve you better. I'm sorry we can't take it on.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$not_fit.type$t$, 'hi', $t$हम घरों और ऑफ़िसों पर ध्यान देते हैं। इस तरह की जगह की ख़ास ज़रूरतें होती हैं, इसलिए इसमें विशेषज्ञता वाला स्टूडियो आपके लिए बेहतर रहेगा। माफ़ कीजिए, हम इसे नहीं ले पाएँगे।$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.type$t$, 'mr', $t$आम्ही घरे आणि ऑफिसेसवर लक्ष केंद्रित करतो. अशा जागेच्या विशेष गरजा असतात, त्यामुळे त्यात तज्ज्ञ असलेला स्टुडिओ तुमच्यासाठी अधिक योग्य ठरेल. क्षमस्व, आम्ही हे घेऊ शकत नाही.$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.size_small$t$, 'en', $t$Our office projects start at about 500 square feet, because our team is set up for that scale. A designer who specialises in compact spaces will be a better fit.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$not_fit.size_small$t$, 'hi', $t$हमारे ऑफ़िस प्रोजेक्ट लगभग 500 वर्ग फ़ुट से शुरू होते हैं, क्योंकि हमारी टीम उसी स्केल के लिए बनी है। छोटी जगहों में विशेषज्ञता रखने वाला डिज़ाइनर आपके लिए बेहतर रहेगा।$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.size_small$t$, 'mr', $t$आमचे ऑफिस प्रोजेक्ट साधारण 500 चौरस फुटांपासून सुरू होतात, कारण आमची टीम त्या प्रमाणासाठी तयार आहे. लहान जागांमध्ये तज्ज्ञ असलेला डिझायनर तुमच्यासाठी अधिक योग्य ठरेल.$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.size_large$t$, 'en', $t$Our office projects go up to about 3,000 square feet, so a space this size needs a larger commercial team than ours. I'm sorry we can't take it on.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$not_fit.size_large$t$, 'hi', $t$हमारे ऑफ़िस प्रोजेक्ट लगभग 3,000 वर्ग फ़ुट तक के होते हैं, इसलिए इतनी बड़ी जगह के लिए हमारी टीम से बड़ी कमर्शियल टीम चाहिए। माफ़ कीजिए, हम इसे नहीं ले पाएँगे।$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.size_large$t$, 'mr', $t$आमचे ऑफिस प्रोजेक्ट साधारण 3,000 चौरस फुटांपर्यंत असतात, त्यामुळे एवढ्या मोठ्या जागेसाठी आमच्यापेक्षा मोठी कमर्शियल टीम लागेल. क्षमस्व, आम्ही हे घेऊ शकत नाही.$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.timeline$t$, 'en', $t$To do this properly, design takes three to four weeks and a room takes at least eight to ten weeks end to end, so we couldn't do justice to your date. If you can start a little later, I can book you in now. Would that work?$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$not_fit.timeline$t$, 'hi', $t$इसे ठीक से करने के लिए डिज़ाइन में तीन से चार हफ़्ते और एक कमरे के लिए शुरू से अंत तक कम से कम आठ से दस हफ़्ते लगते हैं, इसलिए आपकी तारीख़ के साथ हम न्याय नहीं कर पाएँगे। अगर आप थोड़ा देर से शुरू कर सकें, तो हम अभी आपकी बुकिंग कर सकते हैं। क्या यह चलेगा?$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.timeline$t$, 'mr', $t$हे नीट करण्यासाठी डिझाइनला तीन ते चार आठवडे आणि एका खोलीसाठी सुरुवातीपासून शेवटपर्यंत किमान आठ ते दहा आठवडे लागतात, त्यामुळे तुमच्या तारखेला आम्ही न्याय देऊ शकणार नाही. तुम्ही थोडं उशिरा सुरू करू शकलात, तर आम्ही आत्ताच बुकिंग करू शकतो. चालेल का?$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.wardrobe_only$t$, 'en', $t$Our projects start at a full room with design and execution, so a single wardrobe is smaller than we can do well. A local modular carpentry firm will serve you better.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$not_fit.wardrobe_only$t$, 'hi', $t$हमारे प्रोजेक्ट एक पूरे कमरे के डिज़ाइन और एक्ज़िक्यूशन से शुरू होते हैं, इसलिए सिर्फ़ एक वार्डरोब हमारे लिए बहुत छोटा काम है जिसे हम अच्छे से कर सकें। कोई स्थानीय मॉड्यूलर कारपेंट्री फ़र्म आपके लिए बेहतर रहेगी।$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.wardrobe_only$t$, 'mr', $t$आमचे प्रोजेक्ट एका पूर्ण खोलीच्या डिझाइन आणि एक्झिक्यूशनपासून सुरू होतात, त्यामुळे फक्त एक वॉर्डरोब आमच्यासाठी खूप लहान काम आहे. एखादी स्थानिक मॉड्युलर कारपेंट्री फर्म तुमच्यासाठी अधिक योग्य ठरेल.$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.rental_structural$t$, 'en', $t$Because it's a rented home, we keep all work reversible and don't change walls. If you'd like a design within that, I can book a consultation now.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$not_fit.rental_structural$t$, 'hi', $t$क्योंकि यह किराए का घर है, हम सारा काम रिवर्सिबल रखते हैं और दीवारों में बदलाव नहीं करते। अगर आप इसी दायरे में डिज़ाइन चाहें, तो हम अभी कंसल्टेशन बुक कर सकते हैं।$t$, 'draft_pending_native_review', 1, null, null),
($t$not_fit.rental_structural$t$, 'mr', $t$हे भाड्याचं घर असल्यामुळे आम्ही सगळं काम रिव्हर्सिबल ठेवतो आणि भिंतींमध्ये बदल करत नाही. याच मर्यादेत डिझाइन हवं असेल, तर आम्ही आत्ता कन्सल्टेशन बुक करू शकतो.$t$, 'draft_pending_native_review', 1, null, null),
($t$expect_call$t$, 'en', $t$I've passed your details to our team. Someone will call you during working hours, Monday to Friday, 10am to 7pm, {when}.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$expect_call$t$, 'hi', $t$मैंने आपकी जानकारी हमारी टीम को भेज दी है। कोई सोमवार से शुक्रवार, सुबह 10 से शाम 7 बजे के बीच, {when} आपको कॉल करेगा।$t$, 'draft_pending_native_review', 1, null, null),
($t$expect_call$t$, 'mr', $t$मी तुमची माहिती आमच्या टीमकडे दिली आहे. कोणीतरी सोमवार ते शुक्रवार, सकाळी 10 ते संध्याकाळी 7 या वेळेत, {when} तुम्हाला कॉल करेल.$t$, 'draft_pending_native_review', 1, null, null),
($t$complaint_in_hours$t$, 'en', $t$I'm sorry this has happened. I'm connecting you to a senior member of our team now.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$complaint_in_hours$t$, 'hi', $t$जो हुआ उसके लिए मुझे खेद है। आपको अभी हमारी सीनियर टीम से जोड़ा जा रहा है।$t$, 'draft_pending_native_review', 1, null, null),
($t$complaint_in_hours$t$, 'mr', $t$हे घडलं त्याबद्दल मला खेद आहे. तुम्हाला आत्ता आमच्या वरिष्ठ टीमशी जोडलं जात आहे.$t$, 'draft_pending_native_review', 1, null, null),
($t$complaint_after_hours$t$, 'en', $t$I'm sorry this has happened. I've flagged it to our senior team, and a senior person will call you by 10am {when}. You won't need to explain it again.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$complaint_after_hours$t$, 'hi', $t$जो हुआ उसके लिए मुझे खेद है। मैंने इसे हमारी सीनियर टीम को बता दिया है, और {when} सुबह 10 बजे तक कोई सीनियर व्यक्ति आपको कॉल करेगा। आपको दोबारा सब कुछ समझाने की ज़रूरत नहीं होगी।$t$, 'draft_pending_native_review', 1, null, null),
($t$complaint_after_hours$t$, 'mr', $t$हे घडलं त्याबद्दल मला खेद आहे. मी हे आमच्या वरिष्ठ टीमला कळवलं आहे, आणि {when} सकाळी 10 वाजेपर्यंत एक वरिष्ठ व्यक्ती तुम्हाला कॉल करेल. तुम्हाला पुन्हा सगळं समजावून सांगावं लागणार नाही.$t$, 'draft_pending_native_review', 1, null, null),
($t$complaint_transfer_failed$t$, 'en', $t$I couldn't connect you just now. I've alerted our senior team, and a senior person will call you back within 15 minutes.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$complaint_transfer_failed$t$, 'hi', $t$अभी आपकी कॉल जोड़ी नहीं जा सकी। मैंने हमारी सीनियर टीम को अलर्ट कर दिया है, और कोई सीनियर व्यक्ति 15 मिनट के भीतर आपको वापस कॉल करेगा।$t$, 'draft_pending_native_review', 1, null, null),
($t$complaint_transfer_failed$t$, 'mr', $t$आत्ता तुमचा कॉल जोडता आला नाही. मी आमच्या वरिष्ठ टीमला अलर्ट केलं आहे, आणि एक वरिष्ठ व्यक्ती 15 मिनिटांत तुम्हाला परत कॉल करेल.$t$, 'draft_pending_native_review', 1, null, null),
($t$human_requested_in_hours$t$, 'en', $t$Of course. I'm connecting you to our front desk now.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$human_requested_in_hours$t$, 'hi', $t$ज़रूर। आपको अभी हमारे फ़्रंट डेस्क से जोड़ा जा रहा है।$t$, 'draft_pending_native_review', 1, null, null),
($t$human_requested_in_hours$t$, 'mr', $t$नक्कीच. तुम्हाला आत्ता आमच्या फ्रंट डेस्कशी जोडलं जात आहे.$t$, 'draft_pending_native_review', 1, null, null),
($t$human_requested_transfer_failed$t$, 'en', $t$I couldn't connect you just now. I've asked our front desk to call you back within 30 minutes.$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$human_requested_transfer_failed$t$, 'hi', $t$अभी आपकी कॉल जोड़ी नहीं जा सकी। मैंने हमारे फ़्रंट डेस्क से कहा है कि वे 30 मिनट के भीतर आपको वापस कॉल करें।$t$, 'draft_pending_native_review', 1, null, null),
($t$human_requested_transfer_failed$t$, 'mr', $t$आत्ता तुमचा कॉल जोडता आला नाही. मी आमच्या फ्रंट डेस्कला 30 मिनिटांत तुम्हाला परत कॉल करायला सांगितलं आहे.$t$, 'draft_pending_native_review', 1, null, null),
($t$human_requested_after_hours$t$, 'en', $t$Our team is in from 10am to 7pm, Monday to Friday. I can take your details so they call you {whenMorning}, or I can book your consultation myself right now. Which would you prefer?$t$, 'approved', 1, $t$project owner$t$, '2026-10-07'),
($t$human_requested_after_hours$t$, 'hi', $t$हमारी टीम सोमवार से शुक्रवार, सुबह 10 से शाम 7 बजे तक उपलब्ध रहती है। आपकी जानकारी नोट करके उन्हें {whenMorning} कॉल करने के लिए कहा जा सकता है, या अभी यहीं आपकी कंसल्टेशन बुक की जा सकती है। आप कौन सा पसंद करेंगे?$t$, 'draft_pending_native_review', 1, null, null),
